          transform: translateY(100%);
          opacity: 0;
        }
        to {
          transform: translateY(0);
          opacity: 1;
        }
      }

      .update-prompt__content {
        position: relative;
        display: flex;
        align-items: flex-start;
        gap: var(--spacing-md);
        padding: var(--spacing-lg);
        background: var(--color-bg-surface);
        border: 1px solid var(--color-border);
        border-left: 4px solid var(--color-brand);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow-lg);
      }

      .update-prompt__icon {
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        border-radius: var(--radius-md);
        background: var(--color-primary-10);
        color: var(--color-brand);
      }

      .update-prompt__text {
        flex: 1;
        min-width: 0;
      }

      .update-prompt__title {
        display: block;
        margin: 0 0 var(--spacing-xs);
        font-size: var(--fontSize-md);
        font-weight: var(--fontWeight-semibold);
        color: var(--color-text-primary);
        line-height: 1.4;
      }

      .update-prompt__message {
        margin: 0;
        font-size: var(--fontSize-sm);
        color: var(--color-text-secondary);
        line-height: 1.5;
      }

      .update-prompt__actions {
        display: flex;
        gap: var(--spacing-sm);
        margin-top: var(--spacing-md);
      }

      .update-prompt__btn {
        padding: var(--spacing-sm) var(--spacing-md);
        border: none;
        border-radius: var(--radius-md);
        font-size: var(--fontSize-sm);
        font-weight: var(--fontWeight-medium);
        cursor: pointer;
        transition: all var(--motion-duration-base, 160ms) ease-in-out;
        white-space: nowrap;
      }

      .update-prompt__btn--primary {
        background: var(--color-brand);
        color: var(--color-text-inverse);
      }

      .update-prompt__btn--primary:hover:not(:disabled) {
