    | 'primary'
    | 'secondary'
    | 'tertiary'
    | 'success'
    | 'danger' = 'primary';
  @Input() type: 'button' | 'submit' | 'reset' = 'button';
  @Input() disabled = false;
  @Input() icon?: string;
}

