      }

      .cargo,
      .unidade {
        color: #666;
        font-size: 0.95rem;
        padding: 4px 10px;
        background: #f5f5f5;
        border-radius: 4px;
      }

      .status {
        padding: 6px 12px;
        border-radius: 6px;
